# All Code Generated by ChatGPT
import streamlit as st
import pandas as pd
from pathlib import Path

st.title("My Interactive Pie Chart")

# Read the CSV file
file_path = Path(__file__).resolve().parent.parent / "data" / "pie_demo.csv"
df = pd.read_csv(file_path)

# Let the user choose a chart title
chart_title = st.text_input("Chart title", "Example Budget")

# Display the pie chart
st.subheader(chart_title)

st.write("Select a category in the legend to explore the chart.")

st.plotly_chart(
    {
        "data": [{
            "type": "pie",
            "labels": df["Category"],
            "values": df["Value"],
            "hole": 0.3
        }],
        "layout": {"title": chart_title}
    },
    use_container_width=True
)

# Display the source data
st.subheader("Source Data")
st.dataframe(df)
